// Configuração central do agente.
// Tudo que é ajustável fica aqui, para não caçar valor espalhado pelo fluxo.

// ---- origem dos dados ----
// true  = usa o fluxo Mock API do próprio n8n
// false = usa o backend real do time
const usarMock = true;

const urlMock = 'http://localhost:5678/webhook/mock-api?rota=';
const urlApi  = 'https://SEU-BACKEND/api/';

// 'base' já vem montada, então as ferramentas só concatenam a rota.
// Isso evita ternário dentro das expressões do n8n, que é fonte de erro.
const base = usarMock ? urlMock : urlApi;

return [{
  json: {
    usarMock,
    base,

    // Rotas de capacidade (heatmap, alertas, itens...) — dados do Supabase.
    baseCapacidade: 'http://localhost:5678/webhook/capacidade?cenario=1&rota=',

    // ---- segurança ----
    // Segredo combinado com o backend, enviado no header x-origem.
    // Deixe '' para desligar a checagem enquanto testa pelo PowerShell.
    segredoBackend: '',

    // Tamanho máximo da pergunta, em caracteres.
    tamanhoMaximoPergunta: 500,

    // Perguntas por usuário por hora.
    limitePorHora: 20,

    // Teto de requisições por minuto no fluxo inteiro.
    limiteGlobalPorMinuto: 60,

    // Tamanho máximo da resposta devolvida ao app.
    tamanhoMaximoResposta: 4000,

    // true grava o texto da pergunta no log de auditoria.
    registrarPergunta: true,
  },
}];

// ============================================================
// GUARDA DE ENTRADA — primeira barreira do fluxo
// ============================================================
// Roda antes de qualquer chamada paga ou consulta a banco.
// Qualquer coisa fora do esperado derruba a execução pela saída de erro,
// que responde 400 sem explicar o motivo (não entregamos pista a quem sonda).
//
// IMPORTANTE: Settings deste nó > On Error > "Continue (using error output)".
// ============================================================

const cfg     = $('Config').first().json;
const req     = $('Webhook').first().json;
const headers = req.headers || {};
const body    = req.body || {};

// ---- comparação de tempo constante -------------------------------------
// Comparar segredo com === vaza informação por tempo de resposta.
function iguaisSeguro(a, b) {
  a = String(a); b = String(b);
  if (a.length !== b.length) return false;
  let dif = 0;
  for (let i = 0; i < a.length; i++) dif |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return dif === 0;
}

// ---- 1. freio global por minuto ----------------------------------------
// Vale por instância do n8n. Com várias réplicas, cada uma tem o seu contador.
const estado = $getWorkflowStaticData('global');
const minutoAtual = Math.floor(Date.now() / 60000);
if (!estado.global || estado.global.minuto !== minutoAtual) {
  estado.global = { minuto: minutoAtual, contador: 0 };
}
estado.global.contador++;
if (estado.global.contador > cfg.limiteGlobalPorMinuto) {
  throw new Error('BLOQUEIO: teto global por minuto atingido');
}

// ---- 2. segredo compartilhado com o backend ----------------------------
if (cfg.segredoBackend) {
  if (!iguaisSeguro(headers['x-origem'] || '', cfg.segredoBackend)) {
    throw new Error('BLOQUEIO: origem nao autorizada');
  }
}

// ---- 3. credencial presente e no formato certo -------------------------
// Só o formato. Quem valida de verdade é o nó seguinte, contra o servidor.
const auth = headers.authorization || '';
if (!/^Bearer\s+\S+$/i.test(auth.trim())) {
  throw new Error('BLOQUEIO: credencial ausente ou malformada');
}

// ---- 4. corpo da requisição --------------------------------------------
if (typeof body.mensagem !== 'string') {
  throw new Error('BLOQUEIO: campo mensagem ausente ou nao e texto');
}

let mensagem = body.mensagem
  // tira caracteres de controle, que servem para esconder instrução no texto
  .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '')
  // tira marcas invisíveis de direção e largura zero, usadas em prompt injection
  .replace(/[\u200B-\u200F\u202A-\u202E\u2060\uFEFF]/g, '')
  .trim();

// colapsa sequências enormes de espaço ou quebra de linha
mensagem = mensagem.replace(/\n{4,}/g, '\n\n\n').replace(/[ \t]{10,}/g, ' ');

if (!mensagem) {
  throw new Error('BLOQUEIO: mensagem vazia');
}
if (mensagem.length > cfg.tamanhoMaximoPergunta) {
  throw new Error('BLOQUEIO: mensagem acima de ' + cfg.tamanhoMaximoPergunta + ' caracteres');
}

// ---- 5. conversa (opcional) --------------------------------------------
// O app tem várias conversas; cada uma ganha a própria memória no agente.
// Só letras, números, - e _: o id vira parte da chave da memória.
let conversaId = '';
if (body.conversaId !== undefined) {
  if (typeof body.conversaId !== 'string' || !/^[A-Za-z0-9_-]{1,64}$/.test(body.conversaId)) {
    throw new Error('BLOQUEIO: conversaId invalido');
  }
  conversaId = body.conversaId;
}

// ---- 6. idioma da resposta (opcional) ----------------------------------
// O app manda o idioma escolhido; fora da lista, vale o português.
const IDIOMAS = {
  'pt-BR': 'português do Brasil', en: 'inglês', es: 'espanhol', 'zh-CN': 'chinês simplificado',
  ja: 'japonês', de: 'alemão', fr: 'francês',
};
const idioma = Object.prototype.hasOwnProperty.call(IDIOMAS, body.idioma) ? body.idioma : 'pt-BR';
const idiomaNome = IDIOMAS[idioma];

// ---- 7. ignora campos extras -------------------------------------------
// Só passa adiante o que o fluxo usa. Se alguém mandar {"cargo":"DIRETOR"}
// no corpo, morre aqui: identidade vem do token, nunca do cliente.
return [{ json: { mensagem, conversaId, idioma, idiomaNome } }];

// Confere a resposta da rota de identificação do usuário.
// Token inválido -> erro -> saída de erro -> Responder 401.
//
// IMPORTANTE: Settings deste nó > On Error > "Continue (using error output)".

const res = $input.first().json;
const usuario = res.body || {};

if (res.statusCode !== 200 || !usuario.id || !usuario.cargo) {
  throw new Error('Token invalido ou ausente');
}

// Só estes três campos seguem adiante. A identidade vem daqui, do servidor,
// e nunca do corpo da requisição.
return [{
  json: { id: usuario.id, nome: usuario.nome, cargo: usuario.cargo },
}];

// ============================================================
// LIMITE DE USO POR USUÁRIO
// ============================================================
// Roda depois da validação do token, porque só aqui sabemos quem é a pessoa.
// Protege o custo da API de IA e dificulta abuso por conta legítima.
//
// IMPORTANTE: Settings deste nó > On Error > "Continue (using error output)".
// ============================================================

const cfg     = $('Config').first().json;
const usuario = $input.first().json;
const conversaId = $('Guarda de entrada').first().json.conversaId;

const estado = $getWorkflowStaticData('global');
estado.usuarios = estado.usuarios || {};

const horaAtual = Math.floor(Date.now() / 3600000);
const chave = String(usuario.id);

if (!estado.usuarios[chave] || estado.usuarios[chave].hora !== horaAtual) {
  estado.usuarios[chave] = { hora: horaAtual, contador: 0 };
}
estado.usuarios[chave].contador++;

// limpeza: tira usuários de horas antigas para o estado não crescer sem fim
for (const k of Object.keys(estado.usuarios)) {
  if (estado.usuarios[k].hora < horaAtual - 1) delete estado.usuarios[k];
}

if (estado.usuarios[chave].contador > cfg.limitePorHora) {
  throw new Error('BLOQUEIO: limite de ' + cfg.limitePorHora + ' perguntas por hora');
}

return [{
  json: {
    id: usuario.id,
    nome: usuario.nome,
    cargo: usuario.cargo,
    perguntasNaHora: estado.usuarios[chave].contador,
    // chave da memória: uma por conversa do app, sempre dentro do usuário
    sessao: 'central-' + chave + (conversaId ? '-' + conversaId : ''),
  },
}];

// ============================================================
// AUDITORIA E SAÍDA
// ============================================================
// Último nó antes de responder. Registra quem perguntou o quê e
// normaliza a resposta que sai para o app.
// ============================================================

const cfg      = $('Config').first().json;
const usuario  = $('Limite de uso').first().json;
const pergunta = $('Guarda de entrada').first().json.mensagem;
const saida    = $input.first().json;

let resposta = typeof saida.output === 'string' ? saida.output : '';
if (!resposta.trim()) {
  resposta = 'Nao consegui montar uma resposta para essa pergunta.';
}

// corta resposta exagerada (modelo em loop, ferramenta despejando dados)
if (resposta.length > cfg.tamanhoMaximoResposta) {
  resposta = resposta.slice(0, cfg.tamanhoMaximoResposta) + '...';
}

// Registro de auditoria. Sai no log do container:  docker logs -f n8n
// Para guardar em tabela, troque este console.log por um nó Postgres.
console.log(JSON.stringify({
  evento: 'pergunta_assistente',
  em: new Date().toISOString(),
  funcionario_id: usuario.id,
  cargo: usuario.cargo,
  pergunta: cfg.registrarPergunta ? pergunta : '(nao registrado)',
  perguntas_na_hora: usuario.perguntasNaHora,
  tamanho_resposta: resposta.length,
}));

return [{ json: { resposta } }];

